CREATE TYPE "AIBuffType" AS ENUM ('PROMPT','AGENT','WORKFLOW','TOOL'); CREATE TYPE "AIBuffStatus" AS ENUM ('DRAFT','PUBLISHED','RETIRED'); CREATE TYPE "AIBuffRunStatus" AS ENUM ('QUEUED','RUNNING','SUCCEEDED','FAILED');
CREATE TABLE "ai_buffs" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"author_id" UUID NOT NULL,"knowledge_asset_id" UUID NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"type" "AIBuffType" NOT NULL,"status" "AIBuffStatus" NOT NULL DEFAULT 'DRAFT',"permission_codes" TEXT[] DEFAULT ARRAY[]::TEXT[],"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "ai_buffs_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ai_buff_versions" ("id" UUID NOT NULL,"buff_id" UUID NOT NULL,"version" INTEGER NOT NULL,"instructions" TEXT NOT NULL,"input_schema" JSONB NOT NULL,"created_by_id" UUID NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ai_buff_versions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ai_buff_runs" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"buff_id" UUID NOT NULL,"version_id" UUID NOT NULL,"caller_id" UUID NOT NULL,"context_type" TEXT,"context_id" UUID,"input" JSONB NOT NULL,"output" JSONB,"status" "AIBuffRunStatus" NOT NULL DEFAULT 'QUEUED',"provider" TEXT,"model" TEXT,"input_tokens" INTEGER,"output_tokens" INTEGER,"cost_micros" INTEGER,"latency_ms" INTEGER,"attempts" INTEGER NOT NULL DEFAULT 0,"error" TEXT,"idempotency_key" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "ai_buff_runs_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ai_buffs_organization_id_name_key" ON "ai_buffs"("organization_id","name"); CREATE INDEX "ai_buffs_organization_id_status_created_at_idx" ON "ai_buffs"("organization_id","status","created_at"); CREATE UNIQUE INDEX "ai_buff_versions_buff_id_version_key" ON "ai_buff_versions"("buff_id","version"); CREATE UNIQUE INDEX "ai_buff_runs_caller_id_idempotency_key_key" ON "ai_buff_runs"("caller_id","idempotency_key"); CREATE INDEX "ai_buff_runs_organization_id_status_created_at_idx" ON "ai_buff_runs"("organization_id","status","created_at");
ALTER TABLE "ai_buff_versions" ADD CONSTRAINT "ai_buff_versions_buff_id_fkey" FOREIGN KEY ("buff_id") REFERENCES "ai_buffs"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ai_buff_runs" ADD CONSTRAINT "ai_buff_runs_buff_id_fkey" FOREIGN KEY ("buff_id") REFERENCES "ai_buffs"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ai_buff_runs" ADD CONSTRAINT "ai_buff_runs_version_id_fkey" FOREIGN KEY ("version_id") REFERENCES "ai_buff_versions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
